{"packet_id":"D003-01","doc_id":"D003","jurisdiction":"Berkeley, CA","category":"screening_restrictions","lifecycle":"enacted","title":"Fair Chance Access to Housing Ordinance","requirement":"Landlords may not ask about, require disclosure of, or use criminal history in rental advertising, applications, tenant selection, or decisions, including refusing to rent or terminating tenancy based on criminal history.","key_value":null,"coverage_conditions":"Rental housing providers in Berkeley, with exemptions for lifetime sex offenders, public housing/Section 8 properties, owner-occupied properties of 1-3 units, units under rental agreement allowing owner move-back, and units occupied by existing tenants seeking to sublet or add/replace roommates.","applicability":{"conditions":[{"type":"owner","role":"exempt","who":"owner-occupied","unit_limit":3},{"type":"other","text":"Public housing/Section 8 properties limited exemptions"}],"per_tenancy":"Exemptions for lifetime sex offenders; units under a rental agreement allowing owner move-back; units occupied by existing tenants seeking to sublet or add/replace roommates.","coverage_quotes":["Owner-occupied properties (between 1-3 units) in which an owner of record resides in one of the units as their primary residence","Public housing/Section 8 properties limited exemptions","Units under a rental agreement allowing owners to move back to their home in accordance with BMC 13.76.130 A.9"]},"exemptions":"Lifetime sex offenders; public housing/Section 8 properties limited exemptions; owner-occupied properties between 1-3 units; units under rental agreement allowing owner move-back; units occupied by existing tenants seeking to sublet or add/replace roommates.","penalty":"Administrative fines of at least $1,000 and up to $10,000 per violation, civil damages including actual damages or three times one month's rent, punitive damages, attorneys' fees and costs, and injunctive relief.","effective_date":null,"valid_through":null,"citation":"Berkeley Mun. Code ch. 13.106","quoted_span":"The Fair Chance Access to Housing Ordinance prohibits rental housing providers in Berkeley from asking about and using criminal history and/or criminal background checks in their rental housing advertising, applications, tenant selection process, or decision-making.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D003-01","doc_id":"D003","jurisdiction":"Berkeley, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Fair Chance Access to Housing Ordinance – termination and notice","requirement":"A landlord may not terminate a tenancy based on criminal history. If the landlord takes action against a tenant based on criminal history, the landlord must provide written notice and an opportunity to respond.","key_value":null,"coverage_conditions":"Rental housing providers in Berkeley, with exemptions for lifetime sex offenders, public housing/Section 8 properties, owner-occupied properties of 1-3 units, units under rental agreement allowing owner move-back, and units occupied by existing tenants seeking to sublet or add/replace roommates.","applicability":{"conditions":[{"type":"owner","role":"exempt","who":"owner-occupied","unit_limit":3},{"type":"other","text":"Public housing/Section 8 properties limited exemptions"}],"per_tenancy":"Exemptions for lifetime sex offenders; units under a rental agreement allowing owner move-back; units occupied by existing tenants seeking to sublet or add/replace roommates.","coverage_quotes":["Owner-occupied properties (between 1-3 units) in which an owner of record resides in one of the units as their primary residence","Public housing/Section 8 properties limited exemptions","Units under a rental agreement allowing owners to move back to their home in accordance with BMC 13.76.130 A.9"]},"exemptions":"Lifetime sex offenders; public housing/Section 8 properties limited exemptions; owner-occupied properties between 1-3 units; units under rental agreement allowing owner move-back; units occupied by existing tenants seeking to sublet or add/replace roommates.","penalty":"Administrative fines of at least $1,000 and up to $10,000 per violation, civil damages including actual damages or three times one month's rent, punitive damages, attorneys' fees and costs, and injunctive relief.","effective_date":null,"valid_through":null,"citation":"Berkeley Mun. Code ch. 13.106","quoted_span":"Refuse to rent or terminate a tenancy based on criminal history","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
